import React, { useState, useEffect, useCallback } from 'react';
import { Flow, MediaItem } from 'flow-sdk';
import { VectorCanvas } from './components/VectorCanvas';
import { ControlPanel } from './components/ControlPanel';

export default function App() {
  const [backgroundImage, setBackgroundImage] = useState<MediaItem | null>(null);
  const [brushSize, setBrushSize] = useState(12);
  const [paths, setPaths] = useState<Array<{ points: Array<{ x: number, y: number }> }>>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedVideo, setGeneratedVideo] = useState<any>(null);
  const [selectedModel, setSelectedModel] = useState('Veo 3.1 - Quality');
  const [error, setError] = useState<string | null>(null);

  // Cinematic Brief Prompt
  const [cinematicPrompt, setCinematicPrompt] = useState('Cinematic low-angle sweep over an alien desert. Neon glowing flora, hyper-realistic textures, volumetric sand dust, 8k cinematic lighting.');

  // Technical Payloads
  const [trajectoryPayload, setTrajectoryPayload] = useState('');
  const [physicsPayload, setPhysicsPayload] = useState('');

  // Director Board Params
  const [shotType, setShotType] = useState('Cinematic Medium Tracking');
  const [motionVectors, setMotionVectors] = useState<string[]>(['Continuous Dolly Forward']);
  const [motionSpeed, setMotionSpeed] = useState(2);
  const [lockPhysics, setLockPhysics] = useState(true);
  const [duration, setDuration] = useState(8);

  // New Physics Parameters
  const [parallaxDepth, setParallaxDepth] = useState(3);
  const [droneMomentum, setDroneMomentum] = useState(40);

  // Update Trajectory Payload
  useEffect(() => {
    if (paths.length === 0) {
      setTrajectoryPayload('');
      return;
    }
    const formatted = paths.map(path => 
      path.points.map(p => `${Math.round(p.x)},${Math.round(p.y)}`).join(';')
    ).join('|');
    setTrajectoryPayload(`{{drawn_vector_map: ${formatted}}}`);
  }, [paths]);

  // Update Physics Payload
  useEffect(() => {
    const parts = [
      shotType,
      ...motionVectors,
      `MotionSpeed:${motionSpeed}`,
      `ParallaxSeparation:${parallaxDepth}`,
      `AerodynamicDrift:${droneMomentum}%`,
      lockPhysics ? 'GeometryLock:STRICT' : 'NaturalPhysics:ON'
    ];

    // Construct descriptive physics hints based on settings
    let physicsHints = `[Physics Protocol] ${parts.join(', ')}.`;
    if (parallaxDepth > 3) physicsHints += " Force deep 3D parallax separation between foreground and horizon.";
    if (droneMomentum > 60) physicsHints += " Apply natural drone momentum and aerodynamic drift.";
    if (lockPhysics) physicsHints += " Lock scene geometry to eliminate texture morphing or warping.";

    setPhysicsPayload(physicsHints);
  }, [shotType, motionVectors, motionSpeed, parallaxDepth, droneMomentum, lockPhysics]);

  const handleSelectImage = async () => {
    try {
      const media = await Flow.media.select({ filter: 'image' });
      if (media) {
        setBackgroundImage(media);
        setGeneratedVideo(null);
        setPaths([]);
        setError(null);
      }
    } catch (err) {
      console.error('Selection failed:', err);
    }
  };

  const handleGenerate = async () => {
    if (!backgroundImage) return;

    setIsGenerating(true);
    setError(null);
    try {
      const fullPrompt = `${cinematicPrompt}. [Technical Constraints] Trajectory: ${trajectoryPayload}. ${physicsPayload} Duration: ${duration}s.`;

      const result = await Flow.generate.video({
        prompt: fullPrompt,
        firstFrameImageMediaId: backgroundImage.mediaId,
        modelDisplayName: selectedModel,
        aspectRatio: '16:9',
        durationSeconds: duration
      });
      setGeneratedVideo(result);
    } catch (err: any) {
      console.error('Render failed:', err);
      setError(err.message || 'The render engine encountered a physics violation.');
    } finally {
      setIsGenerating(false);
    }
  };

  const handleDownload = async () => {
    if (!generatedVideo) return;
    try {
      await Flow.download({
        base64: generatedVideo.base64,
        mimeType: generatedVideo.mimeType,
        filename: `Cinematic_Master_${Date.now()}.mp4`
      });
    } catch (err) {
      console.error('Download failed:', err);
    }
  };

  useEffect(() => {
    const id = 'director-design-css';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      input[type=range] { -webkit-appearance: none; appearance: none; background: transparent; width: 100%; cursor: pointer; padding: 8px 0; }
      input[type=range]::-webkit-slider-runnable-track { width: 100%; height: 2px; background: #333; border-radius: 9999px; }
      input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 12px; height: 12px; border-radius: 50%; background: white; margin-top: -5px; }
      .dark-scrollbar::-webkit-scrollbar { width: 4px; }
      .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: #333; border-radius: 10px; }
      html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #0e0e0e; font-family: 'Google Sans Text', sans-serif; overflow: hidden; }
      @keyframes pulse-glow {
        0%, 100% { opacity: 0.3; }
        50% { opacity: 0.6; }
      }
      .render-pulse { animation: pulse-glow 2s infinite ease-in-out; }
    `;
    document.head.appendChild(style);
  }, []);

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e] overflow-hidden">
      <main className="flex-1 relative flex items-center justify-center p-12 bg-[#050505]">
        <VectorCanvas 
          backgroundImage={backgroundImage} 
          brushSize={brushSize}
          paths={paths}
          onPathsChange={setPaths}
        />

        {!backgroundImage && (
          <div className="absolute inset-0 flex flex-col items-center justify-center gap-6 z-20">
            <div className="w-16 h-16 rounded-full bg-white/5 flex items-center justify-center border border-white/10">
              <span className="material-symbols-outlined text-3xl text-white/20">video_camera_back</span>
            </div>
            <button 
              onClick={handleSelectImage}
              className="px-8 py-3 bg-white text-black rounded-xl font-bold hover:bg-gray-200 transition-all active:scale-95 shadow-2xl"
            >
              Mount Reference Frame
            </button>
            <p className="text-white/30 text-[11px] tracking-widest uppercase">Director Terminal Offline</p>
          </div>
        )}

        {error && (
          <div className="absolute top-8 left-1/2 -translate-x-1/2 bg-red-500/10 border border-red-500/20 px-4 py-2 rounded-lg text-red-400 text-xs z-50">
            {error}
          </div>
        )}
      </main>

      <ControlPanel 
        cinematicPrompt={cinematicPrompt}
        onCinematicPromptChange={setCinematicPrompt}
        brushSize={brushSize}
        onBrushSizeChange={setBrushSize}
        onClear={() => setPaths([])}
        onUndo={() => setPaths(prev => prev.slice(0, -1))}
        onSelectImage={handleSelectImage}
        onGenerate={handleGenerate}
        onDownload={handleDownload}
        hasPaths={paths.length > 0}
        hasImage={!!backgroundImage}
        trajectoryPayload={trajectoryPayload}
        physicsPayload={physicsPayload}
        isGenerating={isGenerating}
        generatedVideo={generatedVideo}
        shotType={shotType}
        setShotType={setShotType}
        motionVectors={motionVectors}
        setMotionVectors={setMotionVectors}
        motionSpeed={motionSpeed}
        setMotionSpeed={setMotionSpeed}
        lockPhysics={lockPhysics}
        setLockPhysics={setLockPhysics}
        duration={duration}
        setDuration={setDuration}
        selectedModel={selectedModel}
        setSelectedModel={setSelectedModel}
        parallaxDepth={parallaxDepth}
        setParallaxDepth={setParallaxDepth}
        droneMomentum={droneMomentum}
        setDroneMomentum={setDroneMomentum}
      />
    </div>
  );
}

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { MediaItem } from 'flow-sdk';

interface Point { x: number; y: number; }
interface Path { points: Point[]; }

interface VectorCanvasProps {
  backgroundImage: MediaItem | null;
  brushSize: number;
  paths: Path[];
  onPathsChange: (paths: Path[]) => void;
}

export const VectorCanvas: React.FC<VectorCanvasProps> = ({ 
  backgroundImage, 
  brushSize, 
  paths, 
  onPathsChange 
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [currentPath, setCurrentPath] = useState<Point[]>([]);
  const [canvasSize, setCanvasSize] = useState({ width: 0, height: 0 });

  // Handle Resize and Initial Sizing
  const updateSize = useCallback(() => {
    if (!containerRef.current) return;
    const { width, height } = containerRef.current.getBoundingClientRect();
    setCanvasSize({ width, height });
  }, []);

  useEffect(() => {
    window.addEventListener('resize', updateSize);
    updateSize();
    return () => window.removeEventListener('resize', updateSize);
  }, [updateSize]);

  // Main Draw Loop
  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas || canvas.width === 0) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw all completed paths + the active path being drawn
    const allPaths = [...paths];
    if (currentPath.length > 0) {
      allPaths.push({ points: currentPath });
    }

    allPaths.forEach((path) => {
      if (path.points.length < 2) return;

      ctx.beginPath();
      ctx.moveTo(path.points[0].x, path.points[0].y);

      for (let i = 1; i < path.points.length; i++) {
        ctx.lineTo(path.points[i].x, path.points[i].y);
      }

      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = brushSize;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.stroke();

      // Draw vector head (glowing white node)
      const lastPoint = path.points[path.points.length - 1];
      ctx.save();
      ctx.shadowBlur = 15;
      ctx.shadowColor = '#fff';
      ctx.fillStyle = '#fff';
      ctx.beginPath();
      ctx.arc(lastPoint.x, lastPoint.y, 5, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    });
  }, [paths, currentPath, brushSize, canvasSize]); // canvasSize added to fix stale renders

  useEffect(() => {
    draw();
  }, [draw]);

  const getCoordinates = (e: React.MouseEvent | React.TouchEvent): Point => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();

    let clientX, clientY;
    if ('touches' in e && (e as React.TouchEvent).touches.length > 0) {
      clientX = (e as React.TouchEvent).touches[0].clientX;
      clientY = (e as React.TouchEvent).touches[0].clientY;
    } else {
      clientX = (e as React.MouseEvent).clientX;
      clientY = (e as React.MouseEvent).clientY;
    }

    return {
      x: clientX - rect.left,
      y: clientY - rect.top
    };
  };

  const startDrawing = (e: React.MouseEvent | React.TouchEvent) => {
    if (!backgroundImage) return;
    setIsDrawing(true);
    setCurrentPath([getCoordinates(e)]);
  };

  const handleDrawing = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDrawing) return;
    setCurrentPath(prev => [...prev, getCoordinates(e)]);
  };

  const stopDrawing = () => {
    if (!isDrawing) return;
    if (currentPath.length > 1) {
      onPathsChange([...paths, { points: currentPath }]);
    }
    setCurrentPath([]);
    setIsDrawing(false);
  };

  return (
    <div 
      ref={containerRef} 
      className="w-full h-full flex items-center justify-center relative overflow-hidden"
    >
      <div className="relative inline-block">
        {backgroundImage && (
          <img 
            src={`data:${backgroundImage.mimeType};base64,${backgroundImage.base64}`}
            alt="Reference"
            className="max-w-full max-h-full block pointer-events-none select-none opacity-50"
            onLoad={(e) => {
              const img = e.currentTarget;
              setCanvasSize({ width: img.clientWidth, height: img.clientHeight });
            }}
          />
        )}

        <canvas
          ref={canvasRef}
          width={canvasSize.width}
          height={canvasSize.height}
          onMouseDown={startDrawing}
          onMouseMove={handleDrawing}
          onMouseUp={stopDrawing}
          onMouseLeave={stopDrawing}
          onTouchStart={startDrawing}
          onTouchMove={handleDrawing}
          onTouchEnd={stopDrawing}
          className="absolute inset-0 cursor-crosshair"
          style={{ width: canvasSize.width, height: canvasSize.height }}
        />
      </div>
    </div>
  );
};

import React from 'react';
import { SectionLabel, FieldDropdown, RangeSlider, PillButton, SegmentedToggle, TextInput } from './UIPrimitives';
import { VideoGenerateResult } from 'flow-sdk';

interface ControlPanelProps {
  cinematicPrompt: string;
  onCinematicPromptChange: (val: string) => void;
  brushSize: number;
  onBrushSizeChange: (val: number) => void;
  onClear: () => void;
  onUndo: () => void;
  onSelectImage: () => void;
  onGenerate: () => void;
  onDownload: () => void;
  hasPaths: boolean;
  hasImage: boolean;
  trajectoryPayload: string;
  physicsPayload: string;
  isGenerating: boolean;
  generatedVideo: VideoGenerateResult | null;

  // Camera Params
  shotType: string;
  setShotType: (val: string) => void;
  motionVectors: string[];
  setMotionVectors: (val: string[]) => void;
  motionSpeed: number;
  setMotionSpeed: (val: number) => void;
  lockPhysics: boolean;
  setLockPhysics: (val: boolean) => void;
  duration: number;
  setDuration: (val: number) => void;

  // Quality Selection
  selectedModel: string;
  setSelectedModel: (val: string) => void;

  // New Physics Controls
  parallaxDepth: number;
  setParallaxDepth: (val: number) => void;
  droneMomentum: number;
  setDroneMomentum: (val: number) => void;
}

export const ControlPanel: React.FC<ControlPanelProps> = ({
  cinematicPrompt,
  onCinematicPromptChange,
  brushSize,
  onBrushSizeChange,
  onClear,
  onUndo,
  onSelectImage,
  onGenerate,
  onDownload,
  hasPaths,
  hasImage,
  trajectoryPayload,
  physicsPayload,
  isGenerating,
  generatedVideo,
  shotType,
  setShotType,
  motionVectors,
  setMotionVectors,
  motionSpeed,
  setMotionSpeed,
  lockPhysics,
  setLockPhysics,
  duration,
  setDuration,
  selectedModel,
  setSelectedModel,
  parallaxDepth,
  setParallaxDepth,
  droneMomentum,
  setDroneMomentum
}) => {
  const isQualityModel = selectedModel.includes('Quality');

  const toggleVector = (vector: string) => {
    if (motionVectors.includes(vector)) {
      setMotionVectors(motionVectors.filter(v => v !== vector));
    } else {
      setMotionVectors([...motionVectors, vector]);
    }
  };

  const getSpeedLabel = (v: number) => {
    if (v === 1) return 'Slow cinematic panning';
    if (v === 3) return 'Standard narrative speed';
    if (v === 5) return 'Hyper-fast dynamic blur';
    return `Intensity Level ${v}`;
  };

  const getDepthLabel = (v: number) => {
    if (v <= 2) return 'Flat/Atmospheric';
    if (v === 3) return 'Standard Parallax';
    return 'Deep 3D Separation';
  };

  return (
    <div className="w-[340px] h-full border-l border-white/15 flex flex-col bg-[#0e0e0e] z-10 shadow-2xl">
      <div className="p-4 flex flex-col gap-6 overflow-y-auto dark-scrollbar flex-1">

        {/* Output Monitor Section */}
        {(generatedVideo || isGenerating) && (
          <section className="flex flex-col gap-2">
            <SectionLabel>Output Monitor</SectionLabel>
            <div className="relative aspect-video w-full bg-black rounded-xl border border-white/10 overflow-hidden">
              {isGenerating ? (
                <div className="absolute inset-0 flex flex-col items-center justify-center gap-2">
                  <div className="w-8 h-8 border-2 border-white/20 border-t-white rounded-full animate-spin" />
                  <span className="text-[10px] font-medium text-white/40 tracking-[1px] uppercase text-center px-4">
                    Synthesizing Cinematic Physics...
                  </span>
                </div>
              ) : generatedVideo ? (
                <>
                  <video 
                    src={`data:${generatedVideo.mimeType};base64,${generatedVideo.base64}`} 
                    autoPlay 
                    loop 
                    muted 
                    playsInline 
                    className="w-full h-full object-cover"
                  />
                  <div className="absolute bottom-2 right-2 flex gap-2">
                    <button 
                      onClick={onDownload}
                      className="w-8 h-8 rounded-full bg-white text-black flex items-center justify-center hover:bg-gray-200 transition-colors shadow-xl"
                    >
                      <span className="material-symbols-outlined text-[18px]">download</span>
                    </button>
                  </div>
                </>
              ) : null}
            </div>
          </section>
        )}

        {/* Cinematic Briefing Section */}
        <section className="flex flex-col gap-2">
          <SectionLabel>Director Cinematic Brief</SectionLabel>
          <div className="flex flex-col gap-1.5">
            <TextInput 
              value={cinematicPrompt} 
              onChange={onCinematicPromptChange} 
              placeholder="Describe the cinematic action, lighting, and environment..."
              className="h-[80px]"
            />
          </div>
        </section>

        {/* Director Camera Board */}
        <section className="flex flex-col gap-4">
          <SectionLabel>Director Board (Physics & Optics)</SectionLabel>

          <div className="flex flex-col gap-1.5">
            <FieldDropdown 
              label="Optics & Shot Type" 
              value={shotType} 
              options={["Ultra-Wide Establishing Shot", "Cinematic Medium Tracking", "Dynamic Close-Up Focus"]} 
              onChange={setShotType} 
            />

            <div className="flex flex-col gap-1 mt-1">
              <p className="text-[10px] font-medium text-white/30 uppercase tracking-[0.5px] ml-2 mb-1">Kinetic Vectors</p>
              <div className="grid grid-cols-2 gap-1.5">
                {["Continuous Dolly Forward", "Pan Left/Right", "Crane Tilt Ascent", "First-Person Kinetic FPV"].map(vector => (
                  <button
                    key={vector}
                    onClick={() => toggleVector(vector)}
                    className={`h-[34px] px-2 rounded-xl text-[10px] font-medium transition-all border ${
                      motionVectors.includes(vector) 
                      ? 'bg-[#969696] text-black border-[#969696]' 
                      : 'bg-transparent text-white/60 border-[#595959] hover:border-[#7a7a7a]'
                    }`}
                  >
                    {vector.replace('Continuous ', '').replace('First-Person ', '')}
                  </button>
                ))}
              </div>
            </div>

            <RangeSlider 
              label="3D Parallax Depth" 
              value={parallaxDepth} 
              min={1} 
              max={5} 
              step={1} 
              formatValue={getDepthLabel}
              onChange={setParallaxDepth}
            />

            <RangeSlider 
              label="Drone Momentum" 
              value={droneMomentum} 
              min={0} 
              max={100} 
              step={5} 
              formatValue={(v) => `${v}% Drift`}
              onChange={setDroneMomentum}
            />

            <RangeSlider 
              label="Motion Intensity" 
              value={motionSpeed} 
              min={1} 
              max={5} 
              step={1} 
              formatValue={getSpeedLabel}
              onChange={setMotionSpeed}
            />

            <SegmentedToggle 
              label="Master Output Duration"
              value={duration}
              onChange={setDuration}
              items={isQualityModel ? [{ value: 8, label: '8s (Fixed)' }] : [
                { value: 4, label: '4s' },
                { value: 6, label: '6s' },
                { value: 8, label: '8s' },
                { value: 10, label: '10s' },
              ]}
            />

            <div className="flex items-center justify-between p-2 rounded-xl border border-[#595959] hover:border-[#7a7a7a] transition-colors mt-1">
              <div className="flex flex-col">
                <span className="text-[11px] font-medium text-white/80">Strict Geometry Lock</span>
                <span className="text-[9px] text-white/30 italic">Eliminate texture morphing</span>
              </div>
              <button 
                onClick={() => setLockPhysics(!lockPhysics)}
                className={`w-8 h-4 rounded-full relative transition-colors ${lockPhysics ? 'bg-[#969696]' : 'bg-[#333]'}`}
              >
                <div className={`absolute top-0.5 w-3 h-3 rounded-full bg-white transition-all ${lockPhysics ? 'left-[17px]' : 'left-0.5'}`} />
              </button>
            </div>
          </div>
        </section>

        {/* Scene Configuration */}
        <section className="flex flex-col gap-2">
          <SectionLabel>Engine Configuration</SectionLabel>
          <div className="flex flex-col gap-1.5">
            <PillButton 
              variant="outline" 
              icon={<span className="material-symbols-outlined text-[18px]">add_photo_alternate</span>}
              onClick={onSelectImage}
            >
              {hasImage ? 'Replace Reference Frame' : 'Mount Reference Frame'}
            </PillButton>
            <FieldDropdown 
              label="Render Engine Quality" 
              value={selectedModel} 
              options={["Omni Flash", "Veo 3.1 - Fast", "Veo 3.1 - Quality"]} 
              onChange={(val) => {
                setSelectedModel(val);
                if (val.includes('Quality')) setDuration(8);
              }} 
            />
          </div>
        </section>

        {/* Trajectory Board */}
        <section className="flex flex-col gap-3">
          <SectionLabel>Path Vector Trajectory</SectionLabel>
          <div className="flex flex-col gap-1.5">
             <div className="flex gap-1.5">
               <button 
                 onClick={onUndo}
                 disabled={!hasPaths}
                 className="flex-1 h-[34px] rounded-xl border border-[#595959] text-[11px] font-medium hover:bg-white/5 disabled:opacity-20 transition-all flex items-center justify-center gap-1"
               >
                 <span className="material-symbols-outlined text-[16px]">undo</span>
                 Undo Path
               </button>
               <button 
                 onClick={onClear}
                 disabled={!hasPaths}
                 className="flex-1 h-[34px] rounded-xl border border-[#595959] text-[11px] font-medium hover:bg-white/5 disabled:opacity-20 transition-all flex items-center justify-center gap-1"
               >
                 <span className="material-symbols-outlined text-[16px]">restart_alt</span>
                 Reset
               </button>
             </div>
          </div>
        </section>

        {/* Technical Data Out */}
        <section className="flex flex-col gap-2">
          <SectionLabel>Active Metadata Payloads</SectionLabel>
          <div className="flex flex-col gap-2">
            <div className="p-2.5 rounded-xl bg-white/5 border border-white/10 font-mono text-[9px] break-all leading-normal text-blue-400 max-h-32 overflow-y-auto dark-scrollbar">
              <div className="text-white/30 mb-1">PHYSICS_OVERRIDE</div>
              {physicsPayload}
            </div>
            <div className="p-2.5 rounded-xl bg-white/5 border border-white/10 font-mono text-[9px] break-all leading-normal text-emerald-400">
              <div className="text-white/30 mb-1">VECTOR_PATH_MAP</div>
              {trajectoryPayload || '// No active trajectories'}
            </div>
          </div>
        </section>
      </div>

      <div className="p-4 border-t border-white/15 bg-[#0e0e0e]">
        <button 
          onClick={onGenerate}
          disabled={!hasImage || isGenerating}
          className={`w-full h-[44px] rounded-xl flex items-center justify-center gap-2 text-[13px] font-bold transition-all ${
            isGenerating 
            ? 'bg-white/10 text-white/40' 
            : 'bg-white text-black hover:bg-gray-200 active:scale-[0.98]'
          }`}
        >
          {isGenerating ? (
            <>
              <span className="material-symbols-outlined animate-spin text-[18px]">refresh</span>
              Executing Master Render...
            </>
          ) : (
            <>
              <span className="material-symbols-outlined text-[20px]">movie_edit</span>
              Execute Cinematic Render
            </>
          )}
        </button>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';

export const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-1 mb-1">
    <span className="text-[10px] font-bold text-[rgba(218,220,224,0.6)] tracking-[1px] uppercase">
      {children}
    </span>
  </div>
);

export const TextInput: React.FC<{
  value: string; 
  onChange: (val: string) => void; 
  placeholder?: string;
  className?: string;
}> = ({ value, onChange, placeholder, className = '' }) => (
  <textarea 
    value={value} 
    onChange={(e) => onChange(e.target.value)} 
    placeholder={placeholder}
    className={`border border-[#595959] hover:border-[#7a7a7a] focus:border-[#969696] rounded-xl w-full px-3 py-2.5 resize-none bg-transparent text-[11px] font-medium text-white placeholder-[rgba(218,220,224,0.4)] tracking-[0.1px] focus:outline-none transition-colors dark-scrollbar ${className}`} 
  />
);

export const PillButton: React.FC<{
  icon?: React.ReactNode; 
  children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; 
  onClick?: () => void;
  className?: string;
}> = ({ icon, children, variant = 'filled', onClick, className = '' }) => {
  const base = 'flex items-center gap-[6px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer select-none text-[11px]';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black px-4',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 text-white px-4',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black px-4',
  };
  return (
    <button className={`${base} ${variants[variant]} ${className}`} onClick={onClick}>
      {icon && <span className="flex items-center justify-center">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

export const FieldDropdown: React.FC<{
  label: string; 
  value: string; 
  options: string[];
  onChange: (val: string) => void; 
  className?: string;
}> = ({ label, value, options, onChange, className = '' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setIsOpen(false);
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <div ref={ref} className={`relative ${className}`}>
      <button 
        type="button" 
        onClick={() => setIsOpen(!isOpen)}
        className="w-full text-left border border-[#595959] hover:border-[#7a7a7a] transition-colors rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-3 pr-2 pt-1.5 select-none focus:outline-none"
      >
        <p className="text-[10px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.5px] uppercase">{label}</p>
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-medium text-white truncate mr-2">{value}</span>
          <span className={`material-symbols-outlined text-[16px] text-white/40 transition-transform ${isOpen ? 'rotate-180' : ''}`}>expand_more</span>
        </div>
      </button>
      {isOpen && (
        <div className="absolute z-50 top-[calc(100%+4px)] left-0 w-full bg-[#1a1a1a] border border-[#595959] rounded-xl overflow-hidden shadow-2xl animate-dropdown origin-top">
          <div className="max-h-48 overflow-y-auto dark-scrollbar">
            {options.map((opt) => (
              <button 
                key={opt} 
                type="button"
                className={`w-full text-left px-3 py-2.5 text-[11px] font-medium hover:bg-white/10 transition-colors ${value === opt ? 'bg-white/5 text-white' : 'text-white'}`}
                onClick={() => { onChange(opt); setIsOpen(false); }}
              >
                {opt}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export const SegmentedToggle: React.FC<{
  value: string | number;
  items: { value: string | number; label: string; icon?: React.ReactNode }[];
  onChange: (val: any) => void;
  label?: string;
}> = ({ value, items, onChange, label }) => (
  <div className="flex flex-col gap-1 w-full">
    {label && <p className="text-[10px] font-medium text-white/30 uppercase tracking-[0.5px] ml-2">{label}</p>}
    <div className="flex w-full items-center border border-[#595959] rounded-xl overflow-hidden bg-transparent">
      {items.map((item) => (
        <button 
          key={item.value} 
          type="button" 
          onClick={() => onChange(item.value)}
          className={`flex-1 flex items-center justify-center gap-1 h-[34px] text-[11px] font-medium tracking-[0.1px] transition-all cursor-pointer ${
            value === item.value ? 'bg-[#969696] text-black' : 'text-white/60 hover:text-white hover:bg-white/5'
          }`}
        >
          {item.icon}
          <span>{item.label}</span>
        </button>
      ))}
    </div>
  </div>
);

export const RangeSlider: React.FC<{
  label: string; 
  value: number; 
  min: number; 
  max: number;
  step?: number; 
  formatValue?: (val: number) => string;
  onChange: (val: number) => void;
}> = ({ label, value, min, max, step = 1, formatValue = (v) => String(v), onChange }) => (
  <div className="flex flex-col gap-1.5 pt-1 w-full">
    <div className="flex items-center justify-between px-1">
      <span className="text-[11px] font-medium text-white/60 tracking-[0.2px]">{label}</span>
      <span className="text-[10px] font-mono text-[#c7c9cd] bg-white/5 px-1.5 py-0.5 rounded-md">{formatValue(value)}</span>
    </div>
    <div className="px-1 w-full flex items-center h-4">
      <input 
        type="range" 
        min={min} 
        max={max} 
        step={step} 
        value={value}
        onChange={(e) => onChange(Number(e.target.value))} 
      />
    </div>
  </div>
);
